import { useAuth } from "@/_core/hooks/useAuth";
import DashboardLayout from "@/components/DashboardLayout";
import PlatformAdminLayout from "@/components/PlatformAdminLayout";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { startLogin } from "@/const";
import { trpc } from "@/lib/trpc";
import { AdvancedDashboard, ComplaintsPanel, GeneratorDirectorySearch, GeneratorInspector, InvoiceDeliverySettingsPanel, OperationalMonitoringPanel, OwnerLifecyclePanel, OwnerUsagePriorityFiltersPanel, OwnerUsageQuickActionsPanel, OwnerUsageReportPanel, PlatformControlPanel, PlatformRolePoliciesPanel, PublicPlanVisibilityPanel, SmsWalletAdministrationPanel, SubscriptionPackageCatalogPanel, SubscriptionUpgradeRequestsPanel } from "./AdminAdvancedWorkspace";
import OwnerSubscriptionRegistration from "./OwnerSubscriptionRegistration";
import PlatformTweetSmsReport from "./PlatformTweetSmsReport";
import GeneratorOperationsInspector from "./GeneratorOperationsInspector";
import PlatformAccessPanel from "./PlatformAccessPanel";
import TenantAccessInvitationPanel from "./TenantAccessInvitationPanel";
import SupportCenterPage from "./SupportCenterPage";
import { Building2, CalendarClock, CheckCircle2, CircleDollarSign, FileDown, FileSpreadsheet, FileText, Loader2, MessageSquareText, Plus, RefreshCw, ShieldAlert, UsersRound, KeyRound, Copy } from "lucide-react";
import { FormEvent, useEffect, useMemo, useRef, useState } from "react";
import { toast } from "sonner";
import { formatReportDate } from "@/lib/report-design-system";
import { useLocation } from "wouter";
import { downloadReportHtmlAsPdf } from "@/lib/report-pdf";
import { loadExcelJS, loadPdfDependencies } from "@/lib/lazy-report-deps";

type Tab = "overview" | "generators" | "ownerSubscription" | "subscriptionRequests" | "users" | "supportChat" | "finance" | "reports" | "invoiceDelivery" | "tweetSms" | "tweetSmsReport" | "smsWallet" | "complaints" | "notifications" | "announcements" | "security" | "settings";
const inputClass = "h-10 w-full rounded-xl border border-white/10 bg-white/[0.025] px-3 text-sm text-white outline-none transition placeholder:text-slate-600 focus:border-[#F5B800]/70 focus:ring-2 focus:ring-[#F5B800]/15";
const formatNumber = (value: unknown) => new Intl.NumberFormat("ar").format(Number(value ?? 0));
const formatDate = (value: Date | string | null | undefined) => value ? formatReportDate(value) : "—";
const paymentMethodLabels: Record<string, string> = { cash: "نقدي", wallet: "محفظة", bank_transfer: "تحويل بنكي", card: "بطاقة" };
const notificationStatusLabels: Record<string, string> = { pending: "بانتظار المعالجة", processing: "قيد المعالجة", submitted: "مرسلة", delivered: "مرسلة", read: "مرسلة", failed: "غير مرسلة" };

function statusLabel(status?: string) {
  return ({ trial: "تجريبي", active: "فعّال", overdue: "متأخر", suspended: "معلّق", cancelled: "ملغي", expired: "منتهي", archived: "مؤرشف" } as Record<string, string>)[status ?? ""] ?? "غير مهيأ";
}

function HideUnusedSubscriberOverview() {
  useEffect(() => { document.querySelector("h2")?.parentElement?.parentElement?.parentElement; const heading = Array.from(document.querySelectorAll("h2")).find((node) => node.textContent?.includes("مشتركو المنصة")); heading?.closest('[data-slot="card"]')?.remove(); }, []);
  return null;
}

export default function AdminConsolePage() {
  const { user, loading, isAuthenticated } = useAuth();
  const [, setLocation] = useLocation();
  const [tab, setTab] = useState<Tab>("overview");
  const [tenantFilter, setTenantFilter] = useState<number | undefined>();
  const isPlatformSupport = user?.role === "admin" && user.platformRole === "platform_support";
  const isPlatformAdmin = user?.role === "admin" && ["platform_owner", "platform_admin"].includes(user.platformRole ?? "");
  const isFinanceAdmin = user?.role === "admin" && user.platformRole === "finance_admin";
  const isPlatformOwner = user?.platformRole === "platform_owner";
  const utils = trpc.useUtils();
  const overview = trpc.admin.overview.useQuery(tenantFilter ? { tenantId: tenantFilter } : undefined, { enabled: isPlatformAdmin });
  const owners = trpc.admin.listOwners.useQuery(undefined, { enabled: isPlatformAdmin });
  const users = trpc.admin.userDirectory.useQuery(undefined, { enabled: isPlatformAdmin });
  const snapshot = trpc.admin.platformSnapshot.useQuery(undefined, { enabled: isPlatformAdmin });
  const packageCatalog = trpc.powerhub.publicPackageCatalog.useQuery(undefined, { enabled: isPlatformAdmin, staleTime: 30000 });
  const notifications = trpc.admin.listNotifications.useQuery(undefined, { enabled: isPlatformAdmin });
  const security = trpc.admin.securityCenter.useQuery(undefined, { enabled: isPlatformAdmin });
  const smsPlans = trpc.admin.listSmsPlans.useQuery(undefined, { enabled: isPlatformAdmin });
  const tweetSmsAccounts = trpc.admin.listTweetSmsAccounts.useQuery(undefined, { enabled: isPlatformAdmin });
  const refresh = async () => { await Promise.all([utils.admin.overview.invalidate(), utils.admin.listOwners.invalidate(), utils.admin.userDirectory.invalidate(), utils.admin.platformSnapshot.invalidate(), utils.admin.listNotifications.invalidate(), utils.admin.securityCenter.invalidate(), utils.admin.listSmsPlans.invalidate(), utils.admin.listSmsPackageRequests.invalidate(), utils.admin.listTweetSmsAccounts.invalidate(), utils.admin.getPlatformTweetSmsAccount.invalidate(), utils.admin.platformTweetSmsReport.invalidate(), utils.admin.advancedDashboard.invalidate(), utils.admin.operationalMonitoring.invalidate(), utils.admin.listTenantBranchSettings.invalidate(), utils.admin.platformConfiguration.invalidate()]); };
  const createOwner = trpc.admin.createGeneratorOwnerWithTemporaryPassword.useMutation({ onSuccess: async () => { await refresh(); setTab("generators"); toast.success("تم إنشاء صاحب المولد ومولده بحالة انتظار المراجعة. يجب تغيير كلمة المرور عند أول دخول."); }, onError: (error) => toast.error(error.message) });
  const createOwnerSubscription = trpc.admin.createGeneratorOwnerSubscription.useMutation({ onSuccess: async () => { await refresh(); toast.success("تم إنشاء اشتراك صاحب المولد. يضيف المالك بيانات أول مولد بعد دخوله وتغيير كلمة المرور."); }, onError: (error) => toast.error(error.message) });
  const updateSubscription = trpc.admin.updateSubscription.useMutation({ onSuccess: async () => { await refresh(); toast.success("تم تحديث الاشتراك."); }, onError: (error) => toast.error(error.message) });
  const renewSubscription = trpc.admin.renewSubscription.useMutation({ onSuccess: async (result) => { await refresh(); toast.success(`تم التجديد حتى ${formatDate(result.endsAt)} على باقة ${result.packageCode}. تم تجديد ${result.renewedAddons} إضافة وإنهاء ${result.expiredAddons} إضافة.`); }, onError: (error) => toast.error(error.message) });
  const setTenantMembershipStatus = trpc.admin.setTenantMembershipStatus.useMutation({ onSuccess: async (_, input) => { await refresh(); toast.success(input.status === "active" ? "تم تنشيط المستخدم." : input.status === "suspended" ? "تم توقيف المستخدم مؤقتًا." : "تم سحب وصول المستخدم."); }, onError: (error) => toast.error(error.message) });
  const setPlatformAccountStatus = trpc.admin.setPlatformAccountStatus.useMutation({ onSuccess: async (_, input) => { await refresh(); toast.success(input.status === "active" ? "تم تنشيط حساب المنصة." : input.status === "locked" ? "تم قفل حساب المنصة." : "تم تعطيل حساب المنصة."); }, onError: (error) => toast.error(error.message) });
  const attachOwner = trpc.admin.attachOwnerUser.useMutation({ onSuccess: async () => { await refresh(); toast.success("تم ربط حساب المالك بالمساحة والمحطة."); }, onError: (error) => toast.error(error.message) });
  const setGeneratorStatus = trpc.admin.setGeneratorStatus.useMutation({ onSuccess: async () => { await refresh(); toast.success("تم تحديث حالة المولد."); }, onError: (error) => toast.error(error.message) });
  const approvePendingGenerator = trpc.admin.approvePendingGenerator.useMutation({ onSuccess: async () => { await refresh(); toast.success("تمت مراجعة المولد وتفعيله بنجاح."); }, onError: (error) => toast.error(error.message) });
  const recordSecurityEvent = trpc.admin.recordSecurityEvent.useMutation({ onSuccess: async () => { await refresh(); toast.success("تم تسجيل حدث الأمان."); }, onError: (error) => toast.error(error.message) });
  const saveSecuritySetting = trpc.admin.saveSecuritySetting.useMutation({ onSuccess: async () => { await refresh(); toast.success("تم حفظ إعداد الحماية."); }, onError: (error) => toast.error(error.message) });
  const saveTweetSmsAccount = trpc.admin.saveTweetSmsAccount.useMutation({ onSuccess: async () => { await refresh(); toast.success("تم حفظ حساب TweetSMS المشفر لهذا صاحب المولد."); }, onError: (error) => toast.error(error.message) });
  const testTweetSmsAccount = trpc.admin.testTweetSmsAccount.useMutation({ onSuccess: async (result) => { await refresh(); const outcome = result as unknown as { ok: boolean; message?: string | null }; if (outcome.ok) toast.success("تم التحقق من اتصال TweetSMS بنجاح، وحُفظت نتيجة الفحص."); else toast.error(outcome.message ?? "فشل فحص اتصال TweetSMS."); }, onError: (error) => toast.error(error.message) });
  const overviewRows = overview.data?.owners ?? [];
  const reportRows = owners.data ?? [];
  const eligibleUsers = useMemo(() => (users.data ?? []).filter((candidate) => candidate.role !== "admin"), [users.data]);
  const coreDataQueriesFailed = overview.isError || owners.isError || users.isError || snapshot.isError;
  const coreDataFailures: string[] = [];
  if (overview.isError) coreDataFailures.push(`ملخص الإدارة: ${overview.error?.message ?? "تعذر تحديد السبب"}`);
  if (owners.isError) coreDataFailures.push(`قائمة أصحاب المولدات: ${owners.error?.message ?? "تعذر تحديد السبب"}`);
  if (users.isError) coreDataFailures.push(`دليل المستخدمين: ${users.error?.message ?? "تعذر تحديد السبب"}`);
  if (snapshot.isError) coreDataFailures.push(`لقطة المنصة (المولدات والمشتركون والماليات): ${snapshot.error?.message ?? "تعذر تحديد السبب"}`);

  const downloadCsv = () => {
    const rows: Array<Array<string | number>> = [["صاحب المولد", "المساحة", "الحالة", "الخطة", "السكان", "التجاري", "الإجمالي", "ينتهي في"]];
    reportRows.forEach((row) => rows.push([row.owner?.fullName ?? "غير محدد", row.tenant.name, statusLabel(effectiveSubscriptionStatus(row.subscription)), row.subscription?.packageCode ?? "غير محدد", row.subscribers.residential, row.subscribers.commercial, row.subscribers.total, formatDate(row.subscription?.endsAt)]));
    const csv = "\uFEFF" + rows.map((row) => row.map((cell) => `"${String(cell ?? "").replaceAll('"', '""')}"`).join(",")).join("\n");
    const link = document.createElement("a");
    link.href = URL.createObjectURL(new Blob([csv], { type: "text/csv;charset=utf-8" }));
    link.download = "powerhub-platform-admin-report.csv";
    link.click();
    URL.revokeObjectURL(link.href);
  };

  if (loading) return <DashboardLayout><div className="grid min-h-[60vh] place-items-center"><Loader2 className="h-8 w-8 animate-spin text-[#F5B800]" /></div></DashboardLayout>;
  if (!isAuthenticated) return <DashboardLayout><AccessCard title="سجّل الدخول إلى إدارة المنصة" action="تسجيل الدخول" onClick={startLogin} /></DashboardLayout>;
  if (isPlatformSupport) return <SupportCenterPage />;
  if (isFinanceAdmin) return <DashboardLayout><AccessCard title="هذه الصفحة ليست مساحة المدير المالي" detail="تم فصل صلاحيات الإدارة المالية عن مركز إدارة المنصة. افتح المساحة المالية المخصصة لحسابك." action="فتح الإدارة المالية" onClick={() => setLocation("/finance-admin")} /></DashboardLayout>;
  if (!isPlatformAdmin) return <DashboardLayout><AccessCard title="هذه الصفحة مخصصة لآدمن PowerHub" detail="لا يمكن لصاحب مولد أو عضو فريق الوصول إلى بيانات جميع المستأجرين." /></DashboardLayout>;

  return <PlatformAdminLayout activeTab={tab} onTabChange={(nextTab) => setTab(nextTab as Tab)}><main className="space-y-6 pb-12"><header className="rounded-[26px] border border-[#F5B800]/20 bg-[#111823]/85 p-6 shadow-panel"><div className="flex flex-col justify-between gap-5 lg:flex-row lg:items-center"><div><div className="flex items-center gap-2 text-sm font-bold text-[#F5B800]"><ShieldAlert className="h-4 w-4" />إدارة PowerHub العليا</div><h1 className="mt-2 text-2xl font-extrabold text-white">مركز قيادة المنصة</h1><p className="mt-2 max-w-2xl text-sm leading-7 text-slate-400">إشراف مركزي منظم على المولدات والمشتركين والتحصيل والشكاوى وإعدادات الحماية عبر جميع مساحات PowerHub.</p></div><Button variant="outline" onClick={() => void refresh()} className="border-white/10 text-white hover:bg-white/5 hover:text-white"><RefreshCw className="ml-2 h-4 w-4" />تحديث البيانات</Button></div></header>
    {coreDataQueriesFailed ? <Card role="alert" className="border-amber-300/30 bg-amber-300/[.06]"><CardContent className="flex flex-col gap-3 p-4 sm:flex-row sm:items-center sm:justify-between"><div><h2 className="font-bold text-amber-100">تعذر تحميل بعض بيانات المنصة</h2><p className="mt-1 text-sm leading-6 text-slate-400">لن نعرض القوائم الفاشلة كأنها فارغة؛ أعد المحاولة. التفاصيل أدناه تحدد الاستعلام الذي تعذر تحميله.</p><ul className="mt-2 space-y-1 text-xs leading-5 text-amber-100/90">{coreDataFailures.map((failure) => <li key={failure}>{failure}</li>)}</ul></div><Button type="button" variant="outline" onClick={() => void refresh()} className="shrink-0 border-amber-300/30 text-amber-100">إعادة تحميل بيانات المنصة</Button></CardContent></Card> : null}
    {tab === "overview" && <><AdvancedDashboard /><OperationalMonitoringPanel onNavigate={(target) => target === "field_sync" ? window.location.assign("/mobile-sync") : setTab(target)} /><OwnerUsagePriorityFiltersPanel /><OwnerUsageQuickActionsPanel /><OwnerUsageReportPanel /></>}
    {tab === "generators" && <><GeneratorDirectorySearch rows={snapshot.data?.generators?.directory ?? []} /><GeneratorsCenter data={snapshot.data?.generators} pending={setGeneratorStatus.isPending || approvePendingGenerator.isPending} onStatus={setGeneratorStatus.mutate} onApprove={approvePendingGenerator.mutate} /><GeneratorOperationsInspector rows={snapshot.data?.generators?.directory ?? []} /></>}
    {tab === "ownerSubscription" && <OwnerSubscriptionRegistration rows={owners.data ?? []} pending={createOwnerSubscription.isPending} onCreate={createOwnerSubscription.mutateAsync} creationAvailable={true} onGoToFinance={() => setTab("finance")} />}
    {tab === "subscriptionRequests" && <SubscriptionUpgradeRequestsPanel />}
    {tab === "users" && <><HideUnusedSubscriberOverview /><TenantAccessInvitationPanel tenants={owners.data ?? []} tenantsLoading={owners.isLoading} tenantsError={owners.isError} invitations={(snapshot.data?.users?.directory ?? []).filter((row: any) => row.kind === "tenant" && row.invitationStatus === "invited")} /><UsersCenter userSummary={snapshot.data?.users} pending={setTenantMembershipStatus.isPending || setPlatformAccountStatus.isPending} onTenantStatus={setTenantMembershipStatus.mutate} onPlatformStatus={setPlatformAccountStatus.mutate} canManagePlatformAccounts={isPlatformOwner} canResetPasswords={isPlatformAdmin} /><OwnerLifecyclePanel /></>}
    {tab === "supportChat" && <SupportCenterPage embedded />}
    {tab === "finance" && <FinanceCenter data={snapshot.data?.finance} rows={owners.data ?? []} plans={smsPlans.data ?? []} packages={packageCatalog.data?.packages ?? []} pending={updateSubscription.isPending || renewSubscription.isPending} onUpdate={updateSubscription.mutate} onRenew={renewSubscription.mutateAsync} />}
    {tab === "reports" && <><AdminReportsExports rows={reportRows} /><ReportsTab rows={reportRows} onDownload={downloadCsv} data={snapshot.data?.reports} generators={snapshot.data?.generators} /></>}
    {tab === "invoiceDelivery" && <InvoiceDeliverySettingsPanel />}
    {tab === "tweetSms" && <TweetSmsAccountsCenter accounts={tweetSmsAccounts.data ?? []} savePending={saveTweetSmsAccount.isPending} testPending={testTweetSmsAccount.isPending} onSave={saveTweetSmsAccount.mutate} onTest={testTweetSmsAccount.mutate} />}
    {tab === "tweetSmsReport" && <PlatformTweetSmsReport />}
    {tab === "smsWallet" && <SmsWalletAdministrationPanel />}
    {tab === "complaints" && <ComplaintsPanel />}
    {tab === "notifications" && <NotificationsCenter data={snapshot.data?.notifications} rows={notifications.data ?? []} />}
    {tab === "security" && <SecurityCenter data={snapshot.data?.security} security={security.data} pending={recordSecurityEvent.isPending || saveSecuritySetting.isPending} onRecord={recordSecurityEvent.mutate} onSaveSetting={saveSecuritySetting.mutate} />}
    {tab === "settings" && <><PlatformControlPanel /><PublicPlanVisibilityPanel /><SubscriptionPackageCatalogPanel /><PlatformRolePoliciesPanel />{isPlatformOwner && <PlatformAccessPanel />}</>}
  </main></PlatformAdminLayout>;
}

function TweetSmsAccountsCenter({ accounts, savePending, testPending, onSave, onTest }: any) {
  return <section className="space-y-6"><Card className="border-[#F5B800]/25 bg-[#F5B800]/[.035] shadow-panel"><CardContent className="p-5"><div className="flex items-start gap-3"><MessageSquareText className="mt-0.5 h-5 w-5 text-[#F5B800]" /><div><h2 className="font-bold text-white">حسابات TweetSMS لأصحاب المولدات</h2><p className="mt-1 max-w-3xl text-sm leading-7 text-slate-400">تُدار بيانات API واسم المرسل والحد الشهري من آدمن المنصة فقط. لا تُعرض مفاتيح API بعد الحفظ، ولا يراها صاحب المولد أو موظفوه.</p></div></div><p className="mt-4 rounded-xl border border-amber-400/20 bg-amber-400/[.06] p-3 text-xs leading-6 text-amber-200">لكل صاحب مولد حساب مستقل. بعد تغيير المفتاح أو اسم المرسل يتوقف الإرسال حتى ينجح فحص الحساب واسم المرسل والرصيد. تُحتسب الرسالة العربية حتى 70 حرفاً كرسالة واحدة، والنص الأطول بأجزاء 67 حرفاً لكل رسالة متسلسلة.</p></CardContent></Card><div className="space-y-4">{accounts.map((account: any) => <details key={account.tenantId} className="rounded-2xl border border-white/8 bg-[#111823] p-5 shadow-panel"><summary className="cursor-pointer list-none"><div className="flex items-start justify-between gap-3"><div><p className="font-bold text-white">{account.ownerName ?? account.tenantName}</p><p className="mt-1 text-xs text-slate-500">{account.tenantName} · <span dir="ltr">{account.ownerPhone ?? "—"}</span></p><p className="mt-2 text-xs text-slate-400">الحد الفعلي: {account.monthlyLimitMode === "unlimited" ? "غير محدود" : `${formatNumber(account.monthlyLimit)} شريحة`} · المستهلك: {formatNumber(account.usedThisMonth)}</p></div><div className="flex flex-wrap gap-2"><Badge className={account.isActive ? "bg-emerald-400/10 text-emerald-300" : "bg-slate-400/10 text-slate-400"}>{account.isActive ? "الإرسال نشط" : "الإرسال موقوف"}</Badge><Badge className={account.configured ? "bg-sky-400/10 text-sky-300" : "bg-amber-400/10 text-amber-200"}>{account.configured ? "بيانات API محفوظة" : "بانتظار API"}</Badge><span className="text-xs text-[#F5B800]">عرض / إخفاء بيانات الربط</span></div></div></summary><form className="mt-4 space-y-4" onSubmit={(event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const data = new FormData(event.currentTarget); onSave({ tenantId: account.tenantId, apiEndpoint: String(data.get("apiEndpoint") || "") || undefined, apiKey: String(data.get("apiKey") || "") || undefined, apiSecret: String(data.get("apiSecret") || "") || undefined, senderName: String(data.get("senderName")), isActive: data.get("isActive") === "on" }); }}><div className="flex flex-col gap-3 border-b border-white/8 pb-4 lg:flex-row lg:items-start lg:justify-between"><div><p className="font-bold text-white">{account.ownerName ?? account.tenantName}</p><p className="mt-1 text-xs text-slate-500">{account.tenantName} · <span dir="ltr">{account.ownerPhone ?? "—"}</span></p></div><div className="flex flex-wrap gap-2"><Badge className={account.isActive ? "bg-emerald-400/10 text-emerald-300" : "bg-slate-400/10 text-slate-400"}>{account.isActive ? "الإرسال نشط" : "الإرسال موقوف"}</Badge><Badge className={account.configured ? "bg-sky-400/10 text-sky-300" : "bg-amber-400/10 text-amber-200"}>{account.configured ? "بيانات API محفوظة" : "بانتظار API"}</Badge><Badge className={account.lastTestedAt && !account.lastError ? "bg-emerald-400/10 text-emerald-300" : account.lastTestedAt && account.lastError ? "bg-rose-400/10 text-rose-300" : "bg-amber-400/10 text-amber-200"}>{account.lastTestedAt && !account.lastError ? "تم التحقق من الربط" : account.lastTestedAt && account.lastError ? "فشل فحص الربط" : account.configured ? "لم يُفحص الاتصال بعد" : "بانتظار بيانات الربط"}</Badge>{account.subscriptionStatus ? <Badge className="bg-white/5 text-slate-300">الاشتراك: {statusLabel(account.subscriptionStatus)}</Badge> : null}</div></div><div className="mt-5 grid gap-4 lg:grid-cols-2"><label className="block"><span className="mb-2 block text-xs font-bold text-slate-400">رابط API الرسمي</span><Input name="apiEndpoint" type="url" defaultValue={account.apiEndpoint ?? ""} placeholder="https://tweetsms.ps" dir="ltr" className={inputClass} /></label><label className="block"><span className="mb-2 block text-xs font-bold text-slate-400">اسم المرسل المسجّل في TweetSMS</span><Input required name="senderName" defaultValue={account.senderName ?? ""} placeholder="PowerHup" dir="ltr" className={inputClass} /><span className="mt-1 block text-[11px] text-slate-500">لا يُفعّل الحساب إلا بعد نجاح فحص الاسم لدى TweetSMS.</span></label><label className="block"><span className="mb-2 block text-xs font-bold text-slate-400">API Key / Token</span><Input name="apiKey" type="password" autoComplete="new-password" minLength={8} required={!account.configured} placeholder={account.configured ? "اتركه فارغاً للإبقاء على المفتاح الحالي" : "أدخل مفتاح API ليُخزّن مشفراً"} dir="ltr" className={inputClass} /></label><label className="block"><span className="mb-2 block text-xs font-bold text-slate-400">API Secret (اختياري)</span><Input name="apiSecret" type="password" autoComplete="new-password" placeholder="اختياري" dir="ltr" className={inputClass} /></label><div className="rounded-xl border border-white/8 bg-white/[.02] p-3"><p className="text-xs font-bold text-slate-400">الحد الشهري الفعلي وفق سياسة الاشتراك والإضافات</p><p className="mt-2 text-lg font-extrabold text-[#F5B800]">{account.monthlyLimitMode === "unlimited" ? "غير محدود" : `${formatNumber(account.monthlyLimit)} شريحة`}</p><p className="mt-1 text-xs text-slate-500">الاستهلاك المحتسب: {formatNumber(account.usedThisMonth)} شريحة · {account.remaining == null ? "لا يوجد حد متبقٍ ثابت" : `المتبقي: ${formatNumber(account.remaining)} شريحة`}</p>{!account.smsFeatureEligible || !account.smsFeatureEnabled ? <p className="mt-2 text-xs text-amber-200">ميزة SMS غير مؤهلة أو غير مفعلة وفق سياسة الاشتراك الحالية.</p> : null}</div></div><div className="mt-4 flex flex-col gap-3 border-t border-white/8 pt-4 sm:flex-row sm:items-center sm:justify-between"><label className="flex items-center gap-2 text-sm text-slate-300"><input name="isActive" type="checkbox" defaultChecked={account.isActive} className="h-4 w-4 accent-[#F5B800]" />تفعيل الإرسال لهذا المولد</label><div className="flex flex-wrap gap-2"><Button type="button" variant="outline" disabled={testPending || !account.id} onClick={() => onTest({ tenantId: account.tenantId })} className="border-white/15 text-white hover:bg-white/5 hover:text-white">{testPending ? <Loader2 className="ml-2 h-4 w-4 animate-spin" /> : null}فحص الاتصال وتأكيد الربط</Button><Button disabled={savePending} className="bg-[#F5B800] font-bold text-[#0D1117] hover:bg-[#ffd23f]">{savePending ? <Loader2 className="ml-2 h-4 w-4 animate-spin" /> : null}حفظ الحساب</Button></div></div>{account.lastTestedAt && account.lastError ? <p className="mt-3 rounded-xl border border-rose-400/20 bg-rose-400/[.05] px-3 py-2 text-xs leading-6 text-rose-200">فشل آخر فحص اتصال: {account.lastError}</p> : account.lastTestedAt ? <p className="mt-3 rounded-xl border border-emerald-400/20 bg-emerald-400/[.05] px-3 py-2 text-xs leading-6 text-emerald-200">تم التحقق من بيانات الحساب واسم المرسل والاتصال بالمزود في {formatDate(account.lastTestedAt)}.</p> : <p className="mt-3 text-xs leading-6 text-slate-500">{account.configured ? account.lastError ?? "لم يتم التحقق من الربط بعد. استخدم زر فحص الاتصال، ولن يُفعّل الإرسال قبل نجاح الفحص." : "أدخل بيانات الربط واحفظها أولاً، ثم نفّذ فحص الاتصال لإظهار نتيجة مؤكدة."}</p>}</form></details>)}{!accounts.length && <Card className="border-white/8 bg-[#111823]"><CardContent className="p-10 text-center text-sm text-slate-500">لا توجد مساحات أصحاب مولدات مسجلة في المنصة.</CardContent></Card>}</div></section>;
}

function AccessCard({ title, detail, action, onClick }: { title: string; detail?: string; action?: string; onClick?: () => void }) { return <div className="mx-auto mt-14 max-w-xl rounded-[28px] border border-[#F5B800]/20 bg-[#111823] p-8 text-center shadow-panel"><ShieldAlert className="mx-auto h-9 w-9 text-[#F5B800]" /><h1 className="mt-5 text-xl font-extrabold text-white">{title}</h1><p className="mt-3 leading-7 text-slate-400">{detail ?? "يلزم وجود جلسة مصادق عليها للوصول إلى مساحة الإدارة."}</p>{action && <Button onClick={onClick} className="mt-6 bg-[#F5B800] font-bold text-[#0D1117] hover:bg-[#ffd23f]">{action}</Button>}</div>; }
function Metric({ label, value, icon: Icon }: { label: string; value: unknown; icon: typeof UsersRound }) { return <Card className="border-white/8 bg-[#111823] shadow-panel"><CardContent className="p-5"><Icon className="h-5 w-5 text-[#F5B800]" /><p className="mt-5 text-sm text-slate-400">{label}</p><p className="mt-2 font-display text-3xl font-extrabold text-white">{formatNumber(value)}</p></CardContent></Card>; }

const effectiveSubscriptionStatus = (subscription: any) => { if (!subscription) return null; if (subscription.archivedAt) return "archived"; if ((subscription.status === "trial" || subscription.status === "active") && subscription.endsAt && new Date(subscription.endsAt) <= new Date()) return "expired"; return subscription.status; };

function OverviewTab({ totals, rows, tenantFilter, onFilter, snapshot }: any) { return <section className="space-y-6"><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-5"><Metric label="أصحاب المولدات" value={totals?.generatorOwners} icon={Building2} /><Metric label="مشتركو السكان" value={totals?.residential} icon={UsersRound} /><Metric label="المشتركون التجاريون" value={totals?.commercial} icon={CircleDollarSign} /><Metric label="إجمالي المشتركين" value={totals?.subscribers} icon={UsersRound} /><Metric label="اشتراكات فعّالة" value={totals?.activeSubscriptions} icon={CheckCircle2} /></div><div className="grid gap-4 md:grid-cols-3"><Metric label="المولدات العاملة" value={snapshot?.generators?.active} icon={Building2} /><Metric label="الفواتير المتأخرة" value={snapshot?.finance?.overdueCount} icon={CalendarClock} /><Metric label="رسائل تنتظر المعالجة" value={snapshot?.notifications?.statuses?.find((item: any) => item.status === "pending")?.count ?? 0} icon={CheckCircle2} /></div><Card className="border-white/8 bg-[#111823] shadow-panel"><CardContent className="p-5"><div className="mb-5 flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><div><h2 className="font-bold text-white">المشتركون حسب صاحب المولد</h2><p className="mt-1 text-sm text-slate-500">اختر مساحة لعرض أعداد المشتركين المرتبطة بصاحب مولد معين.</p></div><select value={tenantFilter ?? ""} onChange={(event) => onFilter(event.target.value ? Number(event.target.value) : undefined)} className={inputClass + " sm:max-w-xs"}><option value="">كل أصحاب المولدات</option>{rows.map((row: any) => <option key={row.tenant.id} value={row.tenant.id}>{row.owner?.fullName ?? row.tenant.name}</option>)}</select></div><OwnerTable rows={rows} /></CardContent></Card></section>; }

function OwnerTable({ rows }: { rows: any[] }) { return <div className="overflow-x-auto"><table className="w-full min-w-[760px] text-right text-sm"><thead className="text-xs text-slate-500"><tr><th className="pb-3">صاحب المولد</th><th className="pb-3">المساحة</th><th className="pb-3">السكان</th><th className="pb-3">التجاري</th><th className="pb-3">الإجمالي</th><th className="pb-3">الاشتراك</th><th className="pb-3">ينتهي</th></tr></thead><tbody>{rows.map((row) => <tr className="border-t border-white/7" key={row.tenant.id}><td className="py-4 font-bold text-white">{row.owner?.fullName ?? "بانتظار ربط الحساب"}</td><td className="py-4 text-slate-300">{row.tenant.name}</td><td className="py-4">{formatNumber(row.subscribers.residential)}</td><td className="py-4">{formatNumber(row.subscribers.commercial)}</td><td className="py-4 font-bold text-[#F5B800]">{formatNumber(row.subscribers.total)}</td><td className="py-4"><Badge className="bg-white/5 text-slate-300">{statusLabel(row.subscription?.status)}</Badge></td><td className="py-4 text-slate-400">{formatDate(row.subscription?.endsAt)}</td></tr>)}{!rows.length && <tr><td colSpan={7} className="py-10 text-center text-slate-500">لا توجد مساحات أصحاب مولدات مسجلة بعد.</td></tr>}</tbody></table></div>; }

function OwnersTab({ users, rows, pending, onCreate, onAttach }: any) { return <section className="grid gap-6 xl:grid-cols-[.9fr_1.1fr]"><Card className="border-[#F5B800]/20 bg-[#111823] shadow-panel"><CardContent className="p-5"><h2 className="font-bold text-white">إضافة صاحب مولد جديد</h2><p className="mt-1 text-sm leading-6 text-slate-500">ينشئ حساب Supabase ومحطة ومولداً فعلياً بحالة انتظار المراجعة. لا تُخزن كلمة المرور في PowerHub، ويُلزم المالك بتغييرها عند أول دخول.</p><form className="mt-6 space-y-4" onSubmit={(event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const data = new FormData(event.currentTarget); onCreate({ tenantName: String(data.get("tenantName")), slug: String(data.get("slug")).toLowerCase(), ownerName: String(data.get("ownerName")), ownerPhone: String(data.get("ownerPhone")), ownerEmail: String(data.get("ownerEmail")), identityNumber: String(data.get("identityNumber")), generatorName: String(data.get("generatorName")), generatorCode: String(data.get("generatorCode")), generatorCapacityKw: Number(data.get("generatorCapacityKw")), generatorFuelType: String(data.get("generatorFuelType")), companyName: String(data.get("companyName") || "") || undefined, temporaryPassword: String(data.get("temporaryPassword")), siteName: String(data.get("siteName")), siteCode: String(data.get("siteCode")), city: String(data.get("city") || "") || undefined, plan: String(data.get("plan")), subscriptionStatus: String(data.get("subscriptionStatus")), billingCycle: String(data.get("billingCycle")), endsAt: data.get("endsAt") ? new Date(`${String(data.get("endsAt"))}T23:59:59`) : undefined, autoRenew: data.get("autoRenew") === "on", notes: String(data.get("notes") || "") || undefined }); }}><Input required name="tenantName" placeholder="اسم مساحة صاحب المولد" className={inputClass} /><Input required name="slug" placeholder="owner-space-slug" dir="ltr" className={inputClass} /><Input required name="ownerName" placeholder="الاسم الكامل لصاحب المولد" className={inputClass} /><div className="grid gap-3 sm:grid-cols-2"><Input required name="ownerPhone" placeholder="رقم الهاتف الفريد" dir="ltr" className={inputClass} /><Input required name="ownerEmail" type="email" placeholder="البريد الإلكتروني الفريد" dir="ltr" className={inputClass} /></div><div className="grid gap-3 sm:grid-cols-2"><Input required name="identityNumber" placeholder="رقم الهوية" dir="ltr" className={inputClass} /><Input required name="temporaryPassword" type="password" minLength={8} placeholder="كلمة مرور مؤقتة (8+ رموز)" dir="ltr" className={inputClass} /></div><Input name="companyName" placeholder="اسم الشركة أو النشاط" className={inputClass} /><div className="grid gap-3 sm:grid-cols-2"><Input required name="siteName" placeholder="اسم المحطة الأولى" className={inputClass} /><Input required name="siteCode" placeholder="PH-OWNER-01" dir="ltr" className={inputClass} /></div><div className="grid gap-3 sm:grid-cols-2"><Input required name="generatorName" placeholder="اسم المولد الفريد" className={inputClass} /><Input required name="generatorCode" placeholder="GEN-OWNER-01" dir="ltr" className={inputClass} /></div><div className="grid gap-3 sm:grid-cols-2"><Input required name="generatorCapacityKw" type="number" min="0.001" step="0.001" placeholder="قدرة المولد kW" dir="ltr" className={inputClass} /><select required name="generatorFuelType" className={inputClass}><option value="diesel">ديزل</option><option value="gasoline">بنزين</option><option value="gas">غاز</option><option value="other">أخرى</option></select></div><Input name="city" placeholder="المدينة" className={inputClass} /><div className="grid gap-3 sm:grid-cols-2"><select name="plan" className={inputClass}><option value="starter">Starter</option><option value="professional">Professional</option><option value="enterprise">Enterprise</option></select><select name="subscriptionStatus" className={inputClass}><option value="trial">تجريبي</option><option value="active">فعّال</option><option value="suspended">معلّق</option></select></div><div className="grid gap-3 sm:grid-cols-2"><select name="billingCycle" className={inputClass}><option value="monthly">شهري</option><option value="yearly">سنوي</option></select><Input name="endsAt" type="date" className={inputClass} /></div><label className="flex items-center gap-2 text-sm text-slate-400"><input name="autoRenew" type="checkbox" className="accent-[#F5B800]" />تجديد تلقائي</label><textarea name="notes" className="min-h-20 w-full rounded-xl border border-white/10 bg-white/[0.025] p-3 text-sm text-white outline-none focus:border-[#F5B800]/70" placeholder="ملاحظات الاشتراك" /><Button disabled={pending} className="w-full bg-[#F5B800] font-bold text-[#0D1117] hover:bg-[#ffd23f]"><Plus className="ml-2 h-4 w-4" />إنشاء صاحب المولد والمولد المعلّق</Button></form></CardContent></Card><Card className="border-white/8 bg-[#111823] shadow-panel"><CardContent className="p-5"><h2 className="font-bold text-white">أصحاب المولدات المسجلون</h2><div className="mt-4 space-y-3">{rows.map((row: any) => <div className="rounded-xl border border-white/8 bg-white/[0.02] p-4" key={row.tenant.id}><div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><div><p className="font-bold text-white">{row.owner?.fullName ?? "صاحب مولد غير مربوط بحساب"}</p><p className="mt-1 text-xs text-slate-500">{row.tenant.name} · {row.owner?.phone ?? "لا يوجد هاتف"}</p></div><Badge className="w-fit bg-[#F5B800]/10 text-[#F5B800]">{row.tenant.plan}</Badge></div>{!row.owner?.ownerUserId && <div className="mt-4 flex flex-col gap-2 sm:flex-row"><select className={inputClass} defaultValue="" aria-label={`حساب مالك ${row.tenant.name}`}><option value="">اختر حساباً للربط</option>{users.map((candidate: any) => <option key={candidate.id} value={candidate.id}>{candidate.name ?? candidate.email ?? `مستخدم #${candidate.id}`}</option>)}</select><Button variant="outline" className="border-white/10 text-white hover:bg-white/5 hover:text-white" onClick={(event) => { const select = (event.currentTarget.parentElement?.querySelector("select") as HTMLSelectElement | null); if (!select?.value) return toast.error("اختر حساب المستخدم أولاً."); onAttach({ tenantId: row.tenant.id, userId: Number(select.value) }); }}>ربط الحساب</Button></div>}</div>)}{!rows.length && <p className="py-10 text-center text-sm text-slate-500">لم يُضف أي صاحب مولد بعد.</p>}</div></CardContent></Card></section>; }

function SubscriptionsTab({ rows, pending, onUpdate, onRenew, packages = [] }: any) {
  const activeAddonsQuery = trpc.admin.listActiveTenantAddons.useQuery(undefined, { staleTime: 15000 });
  const [renewingId, setRenewingId] = useState<number | null>(null);
  const [renewEndsAt, setRenewEndsAt] = useState("");
  const [renewPackageCode, setRenewPackageCode] = useState<string>("");
  const [addonDecisions, setAddonDecisions] = useState<Record<number, { decision: "renew" | "expire"; durationDays: number }>>({});
  const [renewRequestKeys, setRenewRequestKeys] = useState<Record<number, string>>({});

  const addonLabels: Record<string,string> = {
    fieldUser: "مستخدم ميداني إضافي",
    platformUser: "مستخدم منصة إضافي",
    subscribers50: "50 مشترك إضافي",
    branch: "فرع إضافي",
    sms: "حزمة SMS إضافية",
  };

  const effectiveStatus = (subscription: any) => { if (!subscription) return null; if (subscription.archivedAt) return "archived"; if ((subscription.status === "trial" || subscription.status === "active") && subscription.endsAt && new Date(subscription.endsAt) <= new Date()) return "expired"; return subscription.status; };

  const openRenewal = (row: any) => {
    const subscriptionId = Number(row.subscription?.id ?? 0);
    if (!subscriptionId) { toast.error("لا يوجد اشتراك صالح للتجديد."); return; }
    const currentEnd = row.subscription?.endsAt ? new Date(row.subscription.endsAt) : null;
    const base = currentEnd && !Number.isNaN(currentEnd.getTime()) && currentEnd > new Date() ? currentEnd : new Date();
    const nextEnd = new Date(base);
    nextEnd.setMonth(nextEnd.getMonth() + (row.subscription?.billingCycle === "yearly" ? 12 : 1));
    setRenewingId(subscriptionId);
    setRenewRequestKeys((prev) => ({ ...prev, [subscriptionId]: prev[subscriptionId] ?? crypto.randomUUID() }));
    setRenewEndsAt(nextEnd.toISOString().slice(0,10));
    setRenewPackageCode(String(row.subscription?.packageCode ?? packages[0]?.code ?? ""));
    const tenantAddons = (activeAddonsQuery.data ?? []).filter((item:any) => Number(item.tenantId) === Number(row.tenant.id));
    const next: Record<number, { decision: "renew" | "expire"; durationDays: number }> = {};
    tenantAddons.forEach((item:any) => { next[Number(item.addonRequestId)] = { decision: "renew", durationDays: Number(item.durationDays ?? 30) }; });
    setAddonDecisions(next);
  };

  const submitRenewal = async (row: any) => {
    if (!renewingId || renewingId !== Number(row.subscription?.id)) return;
    if (!renewEndsAt) { toast.error("حدد تاريخ انتهاء التجديد."); return; }
    const addonItems = (activeAddonsQuery.data ?? []).filter((item:any) => Number(item.tenantId) === Number(row.tenant.id));
    const decisions = addonItems.map((item:any) => {
      const selected = addonDecisions[Number(item.addonRequestId)] ?? { decision: "renew" as const, durationDays: Number(item.durationDays ?? 30) };
      return { addonRequestId: Number(item.addonRequestId), decision: selected.decision, ...(selected.decision === "renew" ? { durationDays: selected.durationDays } : {}) };
    });
    try {
      await onRenew({ subscriptionId: Number(row.subscription.id), endsAt: new Date(renewEndsAt + "T23:59:59"), packageCode: renewPackageCode, addonDecisions: decisions, requestKey: renewRequestKeys[Number(row.subscription.id)] });
      setRenewingId(null);
      setRenewRequestKeys((prev) => { const next = { ...prev }; delete next[Number(row.subscription.id)]; return next; });
    } catch {
      // The parent mutation already reports the failure; keep the form open so the admin can correct and retry.
    }
  };

  return <section className="space-y-4">
    {rows.map((row:any) => {
      const tenantAddons = (activeAddonsQuery.data ?? []).filter((item:any) => Number(item.tenantId) === Number(row.tenant.id));
      const isRenewing = renewingId === Number(row.subscription?.id);
      const packageCode = row.subscription?.packageCode ?? row.tenant?.packageCode ?? "basic";
      return <Card className="border-white/8 bg-[#111823] shadow-panel" key={row.tenant.id}>
        <CardContent className="p-5">
          <div className="flex flex-col gap-4 lg:flex-row lg:items-start lg:justify-between">
            <div>
              <p className="font-bold text-white">{row.owner?.fullName ?? row.tenant.name}</p>
              <p className="mt-1 text-sm text-slate-500">{row.tenant.name} · الباقة: <strong className="text-slate-300">{packageCode}</strong> · الحالة: <strong className="text-slate-300">{effectiveStatus(row.subscription) === "expired" ? "منتهي" : effectiveStatus(row.subscription) === "archived" ? "مؤرشف" : effectiveStatus(row.subscription) ?? "—"}</strong> · انتهاء الاشتراك: {formatDate(row.subscription?.endsAt)}</p>
              <p className="mt-1 text-xs text-slate-600">{tenantAddons.length ? `لديه ${tenantAddons.length} إضافة نشطة` : "لا توجد إضافات نشطة مرتبطة بالاشتراك"} · SMS = حصة الباقة + الإضافات النشطة + الشحن المخصص.</p>
            </div>
            <Button disabled={pending || activeAddonsQuery.isLoading} onClick={() => { void (isRenewing ? submitRenewal(row) : openRenewal(row)); }} className="bg-[#F5B800] text-[#0D1117] hover:bg-[#ffd23f]">
              <RefreshCw className="ml-2 h-4 w-4" />{isRenewing ? "تأكيد التجديد وحفظ" : "تجديد الاشتراك"}
            </Button>
          </div>

          {isRenewing && <div className="mt-5 rounded-2xl border border-[#F5B800]/20 bg-[#F5B800]/[.045] p-4">
            <div className="grid gap-3 md:grid-cols-[1fr_1fr_auto]">
              <div><label className="mb-1 block text-xs text-slate-400">ينتهي الاشتراك في</label><Input type="date" value={renewEndsAt} onChange={(e) => setRenewEndsAt(e.target.value)} className={inputClass} /></div>
              <div><label className="mb-1 block text-xs text-slate-400">الباقة عند التجديد</label><select required value={renewPackageCode} onChange={(e) => setRenewPackageCode(e.target.value)} className={inputClass}>{packages.filter((pkg:any) => pkg?.active !== false).map((pkg:any) => <option key={String(pkg.code)} value={String(pkg.code)}>{String(pkg.name ?? pkg.code)}</option>)}</select><p className="mt-1 text-[11px] text-slate-500">يمكن تجديد الاشتراك بنفس الباقة أو نقله إلى باقة أخرى ضمن نفس العملية.</p></div>
              <Button type="button" variant="outline" onClick={() => setRenewingId(null)} className="self-end border-white/10 text-white hover:bg-white/5 hover:text-white">إلغاء</Button>
            </div>

            <div className="mt-5">
              <div className="flex items-center justify-between gap-3"><div><h3 className="font-bold text-white">الإضافات النشطة</h3><p className="mt-1 text-xs leading-5 text-slate-500">يجب أن يحدد الأدمن صراحةً ما إذا كان كل امتياز إضافي سيستمر مع التجديد.</p></div><Badge className="bg-[#F5B800]/10 text-[#F5B800]">{tenantAddons.length} إضافة</Badge></div>
              <div className="mt-3 space-y-2">
                {tenantAddons.map((addon:any) => {
                  const current = addonDecisions[Number(addon.addonRequestId)] ?? { decision:"renew" as const, durationDays:Number(addon.durationDays ?? 30) };
                  return <div key={addon.addonRequestId} className="rounded-xl border border-white/8 bg-[#0D1117]/40 p-3">
                    <div className="flex flex-col gap-3 lg:flex-row lg:items-center lg:justify-between">
                      <div><p className="font-bold text-white">{addonLabels[addon.addonCode] ?? addon.addonCode} × {Number(addon.quantity)}</p><p className="mt-1 text-xs text-slate-500">{addon.addonCode === "sms" ? "تنتهي الإضافة مع نهاية الاشتراك وتُجدد معه عند الاختيار" : `ينتهي: ${formatDate(addon.endsAt)}`}</p></div>
                      <div className="flex flex-wrap items-end gap-2">
                        <select value={current.decision} onChange={(e) => setAddonDecisions((prev) => ({...prev,[Number(addon.addonRequestId)]:{...current,decision:e.target.value as "renew"|"expire"}}))} className={inputClass+" w-36"}>
                          <option value="renew">تجديد الإضافة</option><option value="expire">إنهاء الإضافة</option>
                        </select>
                        {current.decision === "renew" && addon.addonCode !== "sms" && <label className="text-xs text-slate-500">المدة بالأيام<Input type="number" min="1" max="3650" value={current.durationDays} onChange={(e) => setAddonDecisions((prev) => ({...prev,[Number(addon.addonRequestId)]:{...current,durationDays:Math.max(1,Number(e.target.value)||1)}}))} className="mt-1 h-10 w-32"/></label>}
                      </div>
                    </div>
                  </div>;
                })}
                {!tenantAddons.length && <div className="rounded-xl border border-dashed border-white/10 p-4 text-sm text-slate-500">لا توجد إضافات نشطة؛ سيُجدد الاشتراك الأساسي فقط.</div>}
              </div>
            </div>
          </div>}

          <form className="mt-5 grid gap-3 md:grid-cols-5" onSubmit={(event: FormEvent<HTMLFormElement>) => {
            event.preventDefault(); const data = new FormData(event.currentTarget);
            onUpdate({ tenantId: row.tenant.id, packageCode: String(data.get("packageCode")), status: String(data.get("status")), billingCycle: String(data.get("billingCycle")), endsAt: new Date(`${String(data.get("endsAt"))}T23:59:59`), autoRenew: data.get("autoRenew") === "on", notes: String(data.get("notes") || "") || undefined, smsPlanId: null });
          }}>
            <select name="packageCode" defaultValue={packageCode} className={inputClass}>
              {packages.filter((pkg:any) => pkg?.active !== false).map((pkg:any) => <option key={String(pkg.code)} value={String(pkg.code)}>{String(pkg.name ?? pkg.code)}</option>)}
            </select>
            <div className="rounded-xl border border-white/10 bg-white/[.02] px-3 py-2.5 text-xs leading-5 text-slate-400">SMS: <strong className="text-slate-200">حصة الباقة</strong> + <strong className="text-slate-200">إضافات SMS النشطة</strong>. الشحن المخصص منفصل ولا يتحول إلى إضافة عند التجديد.</div>
            <select name="status" defaultValue={row.subscription?.status ?? "trial"} className={inputClass}><option value="trial">تجريبي</option><option value="active">فعّال</option><option value="overdue">متأخر</option><option value="suspended">معلّق</option><option value="cancelled">ملغي</option></select>
            <select name="billingCycle" defaultValue={row.subscription?.billingCycle ?? "monthly"} className={inputClass}><option value="monthly">شهري</option><option value="yearly">سنوي</option></select>
            <Input required name="endsAt" type="date" defaultValue={row.subscription?.endsAt ? new Date(row.subscription.endsAt).toISOString().slice(0,10) : ""} className={inputClass}/>
            <label className="flex items-center gap-2 text-sm text-slate-400"><input defaultChecked={row.subscription?.autoRenew} name="autoRenew" type="checkbox" className="accent-[#F5B800]"/>تجديد تلقائي</label>
            <textarea name="notes" defaultValue={row.subscription?.notes ?? ""} placeholder="ملاحظات" className="min-h-10 rounded-xl border border-white/10 bg-white/[0.025] p-2 text-sm text-white outline-none md:col-span-4"/>
            <Button disabled={pending} className="bg-white/8 text-white hover:bg-white/12">حفظ الاشتراك</Button>
          </form>
        </CardContent>
      </Card>;
    })}
    {!rows.length && <Card className="border-white/8 bg-[#111823]"><CardContent className="p-10 text-center text-slate-500">لا توجد اشتراكات مسجلة حتى الآن.</CardContent></Card>}
  </section>;
}
function AdminReportsExports({ rows }: { rows: any[] }) {
  const pdfRef = useRef<HTMLDivElement>(null);
  const fileRows = rows.map((row) => [row.owner?.fullName ?? "غير محدد", row.tenant.name, statusLabel(row.subscription?.status), row.subscription?.plan ?? row.tenant.plan, row.subscribers.residential, row.subscribers.commercial, row.subscribers.total, formatDate(row.subscription?.endsAt)]);
  const exportExcel = async () => { const { default: ExcelJS } = await loadExcelJS(); const workbook = new ExcelJS.Workbook(); workbook.creator = "PowerHub"; const sheet = workbook.addWorksheet("تقرير الإدارة", { views: [{ rightToLeft: true }] }); sheet.addRow(["تقرير إدارة PowerHub"]); sheet.addRow(["تاريخ الإصدار", new Date().toLocaleDateString("ar-IQ")]); sheet.addRow([]); sheet.addRow(["صاحب المولد", "المساحة", "الحالة", "الخطة", "السكان", "التجاري", "الإجمالي", "ينتهي في"]); fileRows.forEach((row) => sheet.addRow(row)); sheet.columns = [{ width: 28 }, { width: 26 }, { width: 16 }, { width: 16 }, { width: 14 }, { width: 14 }, { width: 14 }, { width: 18 }]; [1, 4].forEach((index) => { const row = sheet.getRow(index); row.font = { bold: true, color: { argb: "FFFFFFFF" } }; row.fill = { type: "pattern", pattern: "solid", fgColor: { argb: "FF0D1117" } }; }); const blob = new Blob([await workbook.xlsx.writeBuffer()], { type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" }); const link = document.createElement("a"); link.href = URL.createObjectURL(blob); link.download = "powerhub-platform-admin-report.xlsx"; link.click(); URL.revokeObjectURL(link.href); toast.success("تم تجهيز تقرير الإدارة بصيغة Excel."); };
  const exportPdf = async () => { if (!pdfRef.current) return; try { const { html2canvas, jsPDF } = await loadPdfDependencies(); const canvas = await html2canvas(pdfRef.current, { scale: 2, backgroundColor: "#ffffff" }); const pdf = new jsPDF("p", "pt", "a4"); const width = pdf.internal.pageSize.getWidth(); const height = canvas.height * width / canvas.width; let offset = 0; const pageHeight = pdf.internal.pageSize.getHeight(); while (offset < height) { pdf.addImage(canvas.toDataURL("image/png"), "PNG", 0, -offset, width, height); offset += pageHeight; if (offset < height) pdf.addPage(); } pdf.save("powerhub-platform-admin-report.pdf"); toast.success("تم تجهيز تقرير الإدارة بصيغة PDF."); } catch { toast.error("تعذر إنشاء PDF لتقرير الإدارة. حاول مرة أخرى."); } };
  return <><Card className="border-[#F5B800]/20 bg-[#F5B800]/[.035] shadow-panel"><CardContent className="flex flex-col gap-3 p-5 lg:flex-row lg:items-center lg:justify-between"><div><h2 className="font-bold text-white">تصدير تقرير الإدارة العليا</h2><p className="mt-1 text-sm leading-6 text-slate-400">ملف رسمي يضم أصحاب المولدات والاشتراكات وأعداد المشتركين في المنصة.</p></div><div className="flex flex-wrap gap-2"><Button onClick={exportExcel} className="bg-[#F5B800] text-[#0D1117] hover:bg-[#ffd23f]"><FileSpreadsheet className="ml-2 h-4 w-4" />Excel</Button><Button onClick={exportPdf} variant="outline" className="border-[#F5B800]/40 text-[#F5B800] hover:bg-[#F5B800]/10 hover:text-[#ffd23f]"><FileText className="ml-2 h-4 w-4" />PDF</Button></div></CardContent></Card><div ref={pdfRef} className="pointer-events-none fixed left-[-9999px] top-0 w-[760px] bg-white p-10 text-right text-[#0D1117]" dir="rtl"><header className="border-b-4 border-[#F5B800] pb-5"><p className="text-sm font-bold text-[#A17400]">POWERHUB — إدارة الطاقة بذكاء</p><h1 className="mt-2 text-3xl font-extrabold">تقرير إدارة المنصة</h1><p className="mt-2 text-sm">تاريخ الإصدار: {new Date().toLocaleDateString("ar-IQ")}</p></header><table className="mt-7 w-full border-collapse text-sm"><thead><tr>{["صاحب المولد", "المساحة", "الحالة", "الخطة", "المشتركون", "ينتهي في"].map((title) => <th className="border border-[#D9DEE5] bg-[#F5F6F8] p-2" key={title}>{title}</th>)}</tr></thead><tbody>{fileRows.map((row, index) => <tr key={index}><td className="border border-[#D9DEE5] p-2">{row[0]}</td><td className="border border-[#D9DEE5] p-2">{row[1]}</td><td className="border border-[#D9DEE5] p-2">{row[2]}</td><td className="border border-[#D9DEE5] p-2">{row[3]}</td><td className="border border-[#D9DEE5] p-2">{row[6]}</td><td className="border border-[#D9DEE5] p-2">{row[7]}</td></tr>)}</tbody></table><p className="mt-7 text-center text-xs text-[#647080]">هذا التقرير صادر إلكترونيًا من PowerHub.</p></div></>;
}

function ReportsTab({ rows, onDownload, data, generators }: { rows: any[]; onDownload: () => void; data: any; generators: any }) { const totals = rows.reduce((acc, row) => ({ owners: acc.owners + 1, subscribers: acc.subscribers + row.subscribers.total, endingSoon: acc.endingSoon + (row.subscription?.endsAt && new Date(row.subscription.endsAt) < new Date(Date.now() + 30 * 86400000) ? 1 : 0) }), { owners: 0, subscribers: 0, endingSoon: 0 }); return <section className="space-y-6"><div className="grid gap-4 md:grid-cols-3"><Metric label="إجمالي المساحات" value={totals.owners} icon={Building2} /><Metric label="إجمالي المشتركين" value={totals.subscribers} icon={UsersRound} /><Metric label="تنتهي خلال 30 يوماً" value={totals.endingSoon} icon={CalendarClock} /></div><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-4"><ReportCard title="أداء المولدات" value={`${formatNumber(generators?.active)} / ${formatNumber(generators?.total)}`} detail="مولدات عاملة من إجمالي المولدات" /><ReportCard title="الاستهلاك العام" value={`${formatNumber(data?.consumptionKwh)} kWh`} detail={`${formatNumber(data?.approvedReadings)} قراءة معتمدة`} /><ReportCard title="تقرير النمو" value={formatNumber(data?.subscribers)} detail={`${formatNumber(data?.tenants)} مساحة نشطة أو مهيأة في المنصة`} /><ReportCard title="تقرير الشكاوى" value="غير مفعّل" detail="لا توجد وحدة شكاوى مرتبطة بالبيانات حتى الآن" /></div><Card className="border-white/8 bg-[#111823] shadow-panel"><CardContent className="p-5"><div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><div><h2 className="font-bold text-white">تقرير المنصة</h2><p className="mt-1 text-sm text-slate-500">ملخص قابل للتصدير لأصحاب المولدات والاشتراكات وأعداد المشتركين.</p></div><Button onClick={onDownload} className="bg-[#F5B800] text-[#0D1117] hover:bg-[#ffd23f]"><FileDown className="ml-2 h-4 w-4" />تصدير CSV</Button></div><div className="mt-5"><OwnerTable rows={rows} /></div></CardContent></Card></section>; }
function ReportCard({ title, value, detail }: { title: string; value: string; detail: string }) { return <Card className="border-white/8 bg-[#111823]"><CardContent className="p-5"><p className="text-sm text-slate-400">{title}</p><p className="mt-3 text-xl font-extrabold text-white">{value}</p><p className="mt-2 text-xs leading-6 text-slate-500">{detail}</p></CardContent></Card>; }

function GeneratorsCenter({ data, pending, onStatus, onApprove }: any) { const rows = data?.directory ?? []; const label = (status: string) => status === "pending" ? "بانتظار المراجعة" : status === "active" ? "يعمل" : status === "maintenance" ? "صيانة" : status === "offline" ? "غير متصل" : status === "blocked" ? "محظور" : "متوقف"; return <section className="space-y-6"><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-6"><Metric label="جميع المولدات" value={data?.total} icon={Building2} /><Metric label="بانتظار المراجعة" value={data?.pending} icon={CalendarClock} /><Metric label="المولدات العاملة" value={data?.active} icon={CheckCircle2} /><Metric label="قيد الصيانة" value={data?.maintenance} icon={CalendarClock} /><Metric label="موقوفة أو غير متصلة" value={data?.stopped} icon={ShieldAlert} /><Metric label="مولدات محظورة" value={data?.blocked} icon={ShieldAlert} /></div><div className="grid gap-6 xl:grid-cols-[1.35fr_.65fr]"><Card className="border-white/8 bg-[#111823] shadow-panel"><CardContent className="p-5"><h2 className="font-bold text-white">جميع المولدات</h2><p className="mt-1 text-sm text-slate-500">قدرة مركبة إجمالية: {formatNumber(data?.capacityKw)} kW</p><div className="mt-5 overflow-x-auto"><table className="w-full min-w-[760px] text-right text-sm"><thead className="text-xs text-slate-500"><tr><th className="pb-3">المولد</th><th className="pb-3">المالك / المحطة</th><th className="pb-3">القدرة</th><th className="pb-3">الحالة</th><th className="pb-3">إجراء المنصة</th></tr></thead><tbody>{rows.map((row: any) => <tr key={row.id} className="border-t border-white/7"><td className="py-4 font-bold text-white">{row.name}<span className="mr-2 text-xs font-normal text-slate-500">{row.code}</span></td><td className="py-4 text-slate-300">{row.tenantName} · {row.siteName}</td><td className="py-4">{row.ratedCapacityKw} kW</td><td className="py-4"><Badge className={row.status === "pending" ? "bg-amber-400/10 text-amber-300" : row.status === "blocked" ? "bg-rose-400/10 text-rose-300" : "bg-white/5 text-slate-300"}>{label(row.status)}</Badge></td><td className="py-4">{row.status === "pending" ? <Button disabled={pending} size="sm" onClick={() => onApprove({ generatorId: row.id })} className="bg-emerald-400 text-[#07120b] hover:bg-emerald-300">اعتماد وتفعيل</Button> : <Button disabled={pending} size="sm" variant="outline" onClick={() => onStatus({ id: row.id, status: row.status === "blocked" ? "active" : "blocked" })} className={row.status === "blocked" ? "border-emerald-400/30 text-emerald-300 hover:bg-emerald-400/10 hover:text-emerald-200" : "border-rose-400/30 text-rose-300 hover:bg-rose-400/10 hover:text-rose-200"}>{row.status === "blocked" ? "رفع الحظر" : "حظر المولد"}</Button>}</td></tr>)}{!rows.length && <tr><td colSpan={5} className="py-10 text-center text-slate-500">لا توجد مولدات مسجلة بعد.</td></tr>}</tbody></table></div></CardContent></Card><Card className="border-white/8 bg-[#111823] shadow-panel"><CardContent className="p-5"><h2 className="font-bold text-white">طلبات المراجعة المعلقة</h2><p className="mt-1 text-sm text-slate-500">أصحاب مولدات وحساباتهم أنشئت، وتنتظر مراجعة المولد قبل تفعيله.</p><div className="mt-5 space-y-3">{(data?.pendingRegistrations ?? []).map((row: any) => <div className="rounded-xl border border-amber-400/15 bg-amber-400/[.03] p-3" key={row.generatorId}><p className="font-bold text-white">{row.generatorName}</p><p className="mt-1 text-xs text-slate-500">{row.generatorCode} · {row.ratedCapacityKw} kW</p><p className="mt-1 text-xs text-slate-500">{row.ownerName} · {row.phone}</p><Button disabled={pending} size="sm" onClick={() => onApprove({ generatorId: row.generatorId })} className="mt-3 w-full bg-emerald-400 text-[#07120b] hover:bg-emerald-300">اعتماد وتفعيل المولد</Button></div>)}{!(data?.pendingRegistrations ?? []).length && <p className="py-6 text-center text-sm text-slate-500">لا توجد طلبات معلقة.</p>}</div><div className="mt-5 rounded-xl border border-dashed border-[#F5B800]/25 bg-[#F5B800]/5 p-3 text-xs leading-6 text-slate-400">يُسجل الاعتماد في سجل التدقيق ويحوّل حالة المولد فقط من انتظار المراجعة إلى فعّال.</div></CardContent></Card></div></section>; }

function UsersCenter({ userSummary, pending, onTenantStatus, onPlatformStatus, canManagePlatformAccounts, canResetPasswords = false }: any) {
  const users = userSummary?.directory ?? [];
  const roleLabels: Record<string,string> = {
    owner:"صاحب مولد", manager:"مدير", accountant:"محاسب", collector:"محصل", technician:"فني", viewer:"مشاهد",
    platform_owner:"مالك المنصة", platform_admin:"آدمن المنصة", platform_support:"دعم", finance_admin:"مالي"
  };
  const [search,setSearch]=useState("");
  const [role,setRole]=useState("all");
  const [status,setStatus]=useState("all");
  const [tenant,setTenant]=useState("all");
  const [site,setSite]=useState("all");
  const [selected,setSelected]=useState<any>(null);
  const [temporaryCredential,setTemporaryCredential]=useState<any>(null);
  const utils = trpc.useUtils();
  const resetPassword = trpc.admin.resetUserPassword.useMutation({ onSuccess: (result) => { setTemporaryCredential(result); if (result.auditRecorded) toast.success("تمت إعادة تعيين كلمة المرور وتسجيل العملية في سجل الأمان."); else toast.error("تم تغيير كلمة المرور وبدأ سجل التدقيق، لكن تعذر تحديث حالة السجل النهائية؛ راجع سجل الأمان."); void utils.admin.userDirectory.invalidate(); void utils.admin.platformSnapshot.invalidate(); }, onError: (error) => toast.error(error.message) });
  const [page,setPage]=useState(1);
  const pageSize=50;

  const tenants = useMemo(() => Array.from(new Map(users.filter((r:any)=>r.tenantId).map((r:any)=>[String(r.tenantId),r.tenantName])).entries()), [users]);
  const sites = useMemo(() => Array.from(new Map(users.filter((r:any)=>r.siteId).map((r:any)=>[String(r.siteId),r.siteName])).entries()), [users]);
  const roles = ["owner","manager","accountant","collector","technician","viewer","platform_admin","platform_support","finance_admin","platform_owner"];

  const filtered=useMemo(()=>users.filter((row:any)=>{
    const hay=`${row.name??""} ${row.email??""} ${row.phone??""} ${row.tenantName??""} ${row.siteName??""}`.toLowerCase();
    const matchesSearch=!search.trim()||hay.includes(search.trim().toLowerCase());
    const matchesRole=role==="all"||row.role===role;
    const effectiveStatus=row.status ?? (row.kind==="platform" ? row.accountStatus : row.membershipStatus);
    const matchesStatus=status==="all"||effectiveStatus===status;
    const matchesTenant=tenant==="all"||String(row.tenantId)===tenant;
    const matchesSite=site==="all"||String(row.siteId)===site;
    return matchesSearch&&matchesRole&&matchesStatus&&matchesTenant&&matchesSite;
  }),[users,search,role,status,tenant,site]);

  const pageCount=Math.max(1,Math.ceil(filtered.length/pageSize));
  const visibleUsers=filtered.slice((page-1)*pageSize,page*pageSize);

  useEffect(()=>{setPage(1)},[search,role,status,tenant,site]);

  const statusLabel=(row:any)=>{
    if(row.status==="invited") return "مدعو";
    if(row.kind==="platform") return row.accountStatus==="active"?"نشط":row.accountStatus==="locked"?"موقوف مؤقتًا":"مسحوب الوصول";
    return row.membershipStatus==="active"?"نشط":row.membershipStatus==="suspended"?"موقوف مؤقتًا":"مسحوب الوصول";
  };
  const requestTenantStatus=(row:any)=>{
    if(row.status==="invited" || !row.userId) return;
    const next=row.membershipStatus==="active" ? "suspended" : row.membershipStatus==="suspended" ? "active" : "active";
    if(row.membershipStatus==="revoked"){
      if(!window.confirm("إعادة تنشيط هذا المستخدم ستعيد عضويته داخل صاحب المولد. هل تريد المتابعة؟")) return;
    }
    onTenantStatus({tenantId:row.tenantId,userId:row.userId,status:next});
  };
  const requestPlatformStatus=(row:any)=>{
    if(row.status==="invited" || !row.userId || !canManagePlatformAccounts) return;
    const next=row.accountStatus==="active" ? "locked" : "active";
    if(row.accountStatus==="disabled"){
      if(!window.confirm("إعادة تنشيط الحساب المعطل تحتاج تأكيدًا صريحًا. هل تريد المتابعة؟")) return;
    }
    onPlatformStatus({userId:row.userId,status:next});
  };

  return <section className="space-y-6">
    <div className="grid gap-4 md:grid-cols-4">
      <Metric label="إجمالي المستخدمين" value={users.length} icon={UsersRound}/>
      <Metric label="المستخدمون النشطون" value={users.filter((r:any)=>r.isActive).length} icon={CheckCircle2}/>
      <Metric label="الموقوفون/المسحوب وصولهم" value={users.filter((r:any)=>["suspended","locked","disabled","revoked"].includes(r.status)).length} icon={ShieldAlert}/>
      <Metric label="آدمن المنصة" value={userSummary?.platformAdmins} icon={ShieldAlert}/>
    </div>

    <Card className="border-white/8 bg-[#111823] shadow-panel">
      <CardContent className="p-5">
        <div className="grid gap-3 lg:grid-cols-6">
          <label className="lg:col-span-2"><span className="mb-2 block text-xs font-bold text-slate-400">بحث بالاسم / الهاتف / البريد</span><Input value={search} onChange={e=>setSearch(e.target.value)} placeholder="اكتب الاسم أو الهاتف أو البريد..." className={inputClass}/></label>
          <label><span className="mb-2 block text-xs font-bold text-slate-400">نوع المستخدم</span><select value={role} onChange={e=>setRole(e.target.value)} className={inputClass}><option value="all">كل الأنواع</option>{roles.map(value=><option key={value} value={value}>{roleLabels[value]}</option>)}</select></label>
          <label><span className="mb-2 block text-xs font-bold text-slate-400">الحالة</span><select value={status} onChange={e=>setStatus(e.target.value)} className={inputClass}><option value="all">كل الحالات</option><option value="active">نشط</option><option value="suspended">موقوف مؤقتًا</option><option value="revoked">مسحوب الوصول</option><option value="locked">موقوف مؤقتًا</option><option value="disabled">مسحوب الوصول</option><option value="invited">مدعو</option></select></label>
          <label><span className="mb-2 block text-xs font-bold text-slate-400">صاحب المولد</span><select value={tenant} onChange={e=>setTenant(e.target.value)} className={inputClass}><option value="all">كل أصحاب المولدات</option>{tenants.map(([id,name])=><option key={String(id)} value={String(id)}>{String(name)}</option>)}</select></label>
          <label><span className="mb-2 block text-xs font-bold text-slate-400">الفرع / المحطة</span><select value={site} onChange={e=>setSite(e.target.value)} className={inputClass}><option value="all">كل الفروع والمحطات</option>{sites.map(([id,name])=><option key={String(id)} value={String(id)}>{String(name)}</option>)}</select></label>
        </div>

        <div className="mt-5 overflow-x-auto"><table className="w-full min-w-[1100px] text-right text-sm"><thead className="text-xs text-slate-500"><tr><th className="pb-3">المستخدم</th><th className="pb-3">النوع</th><th className="pb-3">صاحب المولد</th><th className="pb-3">الفرع / المحطة</th><th className="pb-3">الحالة</th><th className="pb-3">آخر دخول</th><th className="pb-3">الإجراءات</th></tr></thead>
          <tbody>{visibleUsers.map((row:any)=><tr className="border-t border-white/7" key={`${row.kind}-${row.userId??"invite"}-${row.tenantId??"platform"}-${row.id}`}>
            <td className="py-3"><button className="text-right" onClick={()=>setSelected(row)}><p className="font-bold text-white hover:text-[#F5B800]">{row.name??"—"}</p><p className="text-xs text-slate-500" dir="ltr">{row.email??"—"}{row.phone ? ` · ${row.phone}` : ""}</p></button></td>
            <td className="py-3"><Badge className="bg-white/5 text-slate-300">{roleLabels[row.role]??row.role}</Badge></td>
            <td className="py-3 text-slate-400">{row.tenantName??"إدارة المنصة"}</td>
            <td className="py-3 text-slate-400">{row.siteName??"—"}</td>
            <td className="py-3"><Badge className={statusLabel(row)==="نشط"?"bg-emerald-400/10 text-emerald-300":"bg-amber-400/10 text-amber-200"}>{statusLabel(row)}</Badge></td>
            <td className="py-3 text-slate-500">{formatDate(row.lastSignedIn)}</td>
            <td className="py-3">
              {row.status==="invited" ? <span className="text-xs text-slate-500">بانتظار قبول الدعوة</span> :
                row.kind==="platform"
                  ? (canManagePlatformAccounts && row.role!=="platform_owner" ? <Button size="sm" disabled={pending} variant="outline" onClick={()=>requestPlatformStatus(row)}>{row.accountStatus==="active"?"إيقاف مؤقت":row.accountStatus==="disabled"?"إعادة تنشيط بعد تأكيد":"تنشيط"}</Button> : <span className="text-xs text-slate-600">محمي</span>)
                  : <Button size="sm" disabled={pending} variant="outline" onClick={()=>requestTenantStatus(row)}>{row.membershipStatus==="active"?"إيقاف مؤقت":row.membershipStatus==="suspended"?"تنشيط":"إعادة تنشيط بعد تأكيد"}</Button>}
              {row.userId && canResetPasswords && !(row.kind==="platform" && row.role==="platform_owner") ? <Button size="sm" variant="outline" disabled={resetPassword.isPending} className="mr-2 border-amber-400/20 text-amber-200 hover:bg-amber-400/10 hover:text-amber-100" onClick={()=>{ if(window.confirm(`سيتم تغيير كلمة مرور ${row.name??row.email??"هذا المستخدم"} فورًا، وسيُطلب منه تعيين كلمة مرور جديدة عند الدخول. هل تريد المتابعة؟`)) resetPassword.mutate({userId:Number(row.userId)}); }}><KeyRound className="ml-1 h-3.5 w-3.5"/>إعادة تعيين كلمة المرور</Button> : null}
              <Button size="sm" variant="ghost" className="mr-2 text-slate-300 hover:text-white" onClick={()=>setSelected(row)}>عرض التفاصيل</Button>
            </td>
          </tr>)}{!filtered.length&&<tr><td colSpan={7} className="py-10 text-center text-slate-500">لا توجد نتائج مطابقة للفلاتر.</td></tr>}</tbody>
        </table></div>
        <div className="mt-4 flex flex-wrap items-center justify-between gap-3 border-t border-white/8 pt-4">
          <p className="text-xs text-slate-500">عرض {(page-1)*pageSize+1}–{Math.min(page*pageSize,filtered.length)} من {filtered.length}</p>
          <div className="flex items-center gap-2">
            <Button size="sm" variant="outline" disabled={page<=1} onClick={()=>setPage(p=>Math.max(1,p-1))}>السابق</Button>
            <span className="min-w-20 text-center text-xs text-slate-400">صفحة {page} / {pageCount}</span>
            <Button size="sm" variant="outline" disabled={page>=pageCount} onClick={()=>setPage(p=>Math.min(pageCount,p+1))}>التالي</Button>
          </div>
        </div>
        <p className="mt-4 rounded-xl border border-white/8 bg-white/[.02] p-3 text-xs leading-6 text-slate-500">إدارة حالة الحساب المركزي لا تغيّر عضوية المستخدم داخل صاحب المولد. وإيقاف العضوية لا يعطل حساب المنصة. جميع تغييرات الحالة تمر عبر RPC محمي على مستوى قاعدة البيانات وتسجل في السجل المناسب.</p>
      </CardContent>
    </Card>

    <Dialog open={Boolean(temporaryCredential)} onOpenChange={(open)=>{if(!open)setTemporaryCredential(null)}}><DialogContent className="max-w-lg bg-[#111823] text-white">
      <DialogHeader><DialogTitle>كلمة المرور المؤقتة</DialogTitle><DialogDescription className="text-slate-400">أرسلها للمستخدم عبر قناة آمنة. لن تظهر مرة أخرى بعد إغلاق هذه النافذة، ويجب عليه تغييرها عند تسجيل الدخول التالي.</DialogDescription></DialogHeader>
      {temporaryCredential && <div className="space-y-4"><div className="rounded-xl border border-amber-400/25 bg-amber-400/[.06] p-4"><p className="text-sm text-slate-300">المستخدم: <strong className="text-white">{temporaryCredential.userName}</strong></p><div className="mt-3 break-all rounded-lg bg-black/25 p-3 text-center font-mono text-lg font-bold tracking-wide text-amber-200" dir="ltr">{temporaryCredential.temporaryPassword}</div></div><div className="flex flex-wrap justify-end gap-2"><Button variant="outline" className="border-white/10 text-white hover:bg-white/5" onClick={()=>{void navigator.clipboard.writeText(temporaryCredential.temporaryPassword).then(()=>toast.success("تم نسخ كلمة المرور المؤقتة."),()=>toast.error("تعذر النسخ؛ انسخ كلمة المرور يدويًا."));}}><Copy className="ml-2 h-4 w-4"/>نسخ كلمة المرور</Button><Button onClick={()=>setTemporaryCredential(null)} className="bg-[#F5B800] font-bold text-[#0D1117] hover:bg-[#FFD45A]">تم، إغلاق</Button></div><p className="text-xs leading-6 text-slate-500">سُجلت العملية في سجل أمان المنصة دون حفظ كلمة المرور نفسها. أغلق النافذة بعد نسخها وتسليمها بأمان.</p></div>}
    </DialogContent></Dialog>

    <Dialog open={Boolean(selected)} onOpenChange={(open)=>{if(!open)setSelected(null)}}><DialogContent className="max-w-2xl bg-[#111823] text-white">
      <DialogHeader><DialogTitle>تفاصيل المستخدم</DialogTitle><DialogDescription className="text-slate-400">عرض موحد لحالة الحساب والعضوية والصلاحيات دون تعديل البيانات من هذه النافذة.</DialogDescription></DialogHeader>
      {selected && <div className="grid gap-3 sm:grid-cols-2">
        <Detail label="الاسم" value={selected.name}/><Detail label="البريد" value={selected.email} ltr/>
        <Detail label="الهاتف" value={selected.phone} ltr/><Detail label="نوع المستخدم" value={roleLabels[selected.role]??selected.role}/>
        <Detail label="حالة الحساب" value={selected.accountStatus==="active"?"نشط":selected.accountStatus??"—"}/>
        <Detail label="حالة العضوية" value={selected.membershipStatus==="active"?"نشط":selected.membershipStatus??"—"}/>
        <Detail label="صاحب المولد" value={selected.tenantName}/><Detail label="الفرع / المحطة" value={selected.siteName}/>
        <Detail label="آخر دخول" value={formatDate(selected.lastSignedIn)}/><Detail label="مصدر السجل" value={selected.kind==="platform"?"حساب المنصة":"عضوية صاحب المولد"}/>
      </div>}
    </DialogContent></Dialog>

    <Card className="border-white/8 bg-[#111823]"><CardContent className="p-5"><h2 className="font-bold text-white">صلاحيات الأدوار</h2><div className="mt-4 grid gap-3 sm:grid-cols-2 xl:grid-cols-3"><RolePolicy role="آدمن المنصة" detail="إدارة المنصة والمساحات والاشتراكات والتقارير العامة." /><RolePolicy role="صاحب المولد" detail="إدارة مستأجره ومحطاته وفريقه فقط." /><RolePolicy role="المدير / المحاسب" detail="تشغيل وفوترة وتحكم مالي حسب تعيين المحطة." /><RolePolicy role="المحصل" detail="تحصيل ضمن جلسة ميدانية مفتوحة." /><RolePolicy role="الفني" detail="العدادات والقراءات والمولدات حسب التعيين." /><RolePolicy role="المشاهد" detail="عرض البيانات المصرح بها بلا تعديل." /><RolePolicy role="دعم" detail="دعم وتشخيص وفق الصلاحية الممنوحة." /><RolePolicy role="مالي" detail="عمليات مالية محددة دون إدارة المنصة العليا." /></div></CardContent></Card>
  </section>;
}
function Detail({label,value,ltr=false}:{label:string;value:any;ltr?:boolean}){return <div className="rounded-xl border border-white/8 bg-white/[.02] p-3"><p className="text-xs text-slate-500">{label}</p><p className="mt-1 font-semibold text-white" dir={ltr?"ltr":"rtl"}>{value??"—"}</p></div>}

function RolePolicy({ role, detail }: { role: string; detail: string }) { return <div className="rounded-xl border border-white/8 bg-white/[.02] p-3"><p className="font-bold text-white">{role}</p><p className="mt-1 text-xs leading-6 text-slate-500">{detail}</p></div>; }

function FinanceCenter({ data, rows, pending, onUpdate, onRenew, packages = [] }: any) { const collections = data?.collectionsByGenerator ?? []; return <section className="space-y-6"><div className="grid gap-4 md:grid-cols-4"><Metric label="إيراد الفواتير" value={data?.issuedAmount} icon={CircleDollarSign} /><Metric label="الدفعات المكتملة" value={data?.completedAmount} icon={CheckCircle2} /><Metric label="فواتير متأخرة" value={data?.overdueCount} icon={CalendarClock} /><Metric label="رصيد متأخر" value={data?.overdueAmount} icon={ShieldAlert} /></div><div className="grid gap-6 xl:grid-cols-[.85fr_1.15fr]"><Card className="border-white/8 bg-[#111823] shadow-panel"><CardContent className="p-5"><h2 className="font-bold text-white">طرق الدفع الإلكتروني</h2><p className="mt-1 text-sm text-slate-500">إجمالي الدفعات المكتملة المسجلة من مستأجري المنصة.</p><div className="mt-5 space-y-3">{(data?.paymentMethods ?? []).map((row: any) => <div className="flex items-center justify-between rounded-xl border border-white/8 bg-white/[.02] p-3" key={row.method}><span className="text-slate-300">{paymentMethodLabels[String(row.method)] ?? row.method}</span><span className="font-bold text-[#F5B800]">{formatNumber(row.amount)} · {formatNumber(row.count)} دفعة</span></div>)}{!(data?.paymentMethods ?? []).length && <p className="py-6 text-center text-sm text-slate-500">لا توجد دفعات مسجلة بعد.</p>}</div></CardContent></Card><Card className="border-white/8 bg-[#111823] shadow-panel"><CardContent className="p-5"><h2 className="font-bold text-white">تقارير التحصيل حسب المولد</h2><p className="mt-1 text-sm leading-7 text-slate-500">الدفعات المكتملة المربوطة بعدادات مولدات المنصة.</p><div className="mt-4 max-h-72 overflow-auto"><table className="w-full min-w-[520px] text-right text-sm"><thead className="text-xs text-slate-500"><tr><th className="pb-3">المولد</th><th className="pb-3">المساحة</th><th className="pb-3">الدفعات</th><th className="pb-3">الإجمالي</th></tr></thead><tbody>{collections.map((row: any) => <tr className="border-t border-white/7" key={row.generatorId}><td className="py-3 text-white">{row.generatorName}<span className="mr-2 text-xs text-slate-500">{row.generatorCode}</span></td><td className="py-3 text-slate-400">{row.tenantName}</td><td className="py-3 text-slate-300">{formatNumber(row.count)}</td><td className="py-3 font-bold text-[#F5B800]">{formatNumber(row.amount)}</td></tr>)}{!collections.length && <tr><td colSpan={4} className="py-8 text-center text-slate-500">لا توجد دفعات مكتملة مرتبطة بمولدات بعد.</td></tr>}</tbody></table></div></CardContent></Card></div><div><h2 className="mb-3 text-lg font-extrabold text-white">الاشتراكات والتجديد</h2><SubscriptionsTab rows={rows} pending={pending} onUpdate={onUpdate} onRenew={onRenew} packages={packages} /></div></section>; }

function NotificationsCenter({ data, rows }: any) { return <section className="space-y-6"><div className="grid gap-6 xl:grid-cols-[.8fr_1.2fr]"><Card className="border-white/8 bg-[#111823] shadow-panel"><CardContent className="p-5"><h2 className="font-bold text-white">تنبيهات النظام</h2><p className="mt-1 text-sm text-slate-500">ملخص رسائل WhatsApp وSMS في طوابير المستأجرين.</p><div className="mt-5 space-y-3">{(data?.statuses ?? []).map((item: any) => <div key={item.status} className="flex items-center justify-between rounded-xl border border-white/8 bg-white/[.02] p-3"><span className="text-slate-300">{notificationStatusLabels[String(item.status)] ?? item.status}</span><span className="font-bold text-[#F5B800]">{formatNumber(item.count)}</span></div>)}{!(data?.statuses ?? []).length && <p className="py-8 text-center text-sm text-slate-500">لا توجد رسائل في السجل بعد.</p>}</div></CardContent></Card><Card className="border-white/8 bg-[#111823] shadow-panel"><CardContent className="p-5"><h2 className="font-bold text-white">إرسال إشعار جماعي</h2><p className="mt-2 text-sm leading-7 text-slate-400">إرسال الجماعي إلى قنوات WhatsApp أو SMS معطل في النسخة المحلية حتى يفعّل آدمن المنصة مزوداً خارجياً ويحدد سياسة موافقة لكل مستأجر.</p><textarea disabled placeholder="نص الإشعار الجماعي سيظهر هنا بعد تفعيل القنوات." className="mt-5 min-h-28 w-full rounded-xl border border-white/10 bg-white/[.02] p-3 text-sm text-slate-500" /><Button disabled className="mt-3 w-full bg-white/10 text-slate-500">الإرسال الجماعي مؤجل</Button><div className="mt-4 rounded-xl border border-dashed border-[#F5B800]/25 bg-[#F5B800]/5 p-3 text-xs leading-6 text-slate-400">لا ينفذ مركز الآدمن أي إرسال خارجي من هذه الواجهة قبل تفعيل القنوات والموافقات.</div></CardContent></Card></div><Card className="border-white/8 bg-[#111823] shadow-panel"><CardContent className="p-5"><h2 className="font-bold text-white">سجل الإشعارات</h2><div className="mt-4 overflow-x-auto"><table className="w-full min-w-[760px] text-right text-sm"><thead className="text-xs text-slate-500"><tr><th className="pb-3">المستأجر</th><th className="pb-3">القناة / الحدث</th><th className="pb-3">المستلم</th><th className="pb-3">الحالة</th><th className="pb-3">المحاولات</th><th className="pb-3">التاريخ</th></tr></thead><tbody>{rows.map((row: any) => <tr className="border-t border-white/7" key={row.id}><td className="py-3 text-white">{row.tenantName}</td><td className="py-3 text-slate-400">{row.channel} · {row.eventType}</td><td className="py-3 text-slate-400" dir="ltr">{row.recipient}</td><td className="py-3"><Badge className="bg-white/5 text-slate-300">{notificationStatusLabels[row.status] ?? row.status}</Badge></td><td className="py-3 text-slate-400">{formatNumber(row.attempts)}</td><td className="py-3 text-slate-400">{formatDate(row.createdAt)}</td></tr>)}{!rows.length && <tr><td colSpan={6} className="py-8 text-center text-slate-500">لا توجد إشعارات مسجلة حتى الآن.</td></tr>}</tbody></table></div></CardContent></Card></section>; }

function SecurityCenter({ data, security, pending, onRecord, onSaveSetting }: any) { const events = security?.events ?? []; const settings = security?.settings ?? []; return <section className="space-y-6"><div className="grid gap-6 xl:grid-cols-2"><Card className="border-white/8 bg-[#111823] shadow-panel"><CardContent className="p-5"><h2 className="font-bold text-white">سجل النشاطات</h2><p className="mt-1 text-sm text-slate-500">آخر نشاطات المراجعة المسجلة في مساحات المستأجرين.</p><div className="mt-5 max-h-96 space-y-3 overflow-auto">{(data?.recentAudit ?? []).map((row: any) => <div className="rounded-xl border border-white/8 bg-white/[.02] p-3" key={row.id}><div className="flex items-center justify-between gap-3"><p className="font-bold text-white">{row.action}</p><span className="text-xs text-slate-500">{formatDate(row.createdAt)}</span></div><p className="mt-1 text-xs text-slate-500">{row.tenantName ?? "—"} · {row.siteName ?? "—"} · {row.userName ?? "نظام"}</p></div>)}{!(data?.recentAudit ?? []).length && <p className="py-8 text-center text-sm text-slate-500">لا توجد سجلات تدقيق بعد.</p>}</div></CardContent></Card><Card className="border-white/8 bg-[#111823] shadow-panel"><CardContent className="p-5"><h2 className="font-bold text-white">أحداث الأمان والنسخ الاحتياطي</h2><p className="mt-1 text-sm text-slate-500">سجل تشغيلي مركزي لمحاولات الدخول المرصودة ونتائج النسخ أو التغييرات الأمنية.</p><div className="mt-5 max-h-96 space-y-3 overflow-auto">{events.map((event: any) => <div className="rounded-xl border border-white/8 bg-white/[.02] p-3" key={event.id}><div className="flex items-center justify-between gap-3"><p className="font-bold text-white">{event.title}</p><Badge className={event.severity === "critical" ? "bg-rose-400/10 text-rose-300" : "bg-white/5 text-slate-300"}>{event.eventType}</Badge></div><p className="mt-1 text-xs text-slate-500">{event.details ?? "لا توجد تفاصيل"} · {formatDate(event.createdAt)}</p></div>)}{!events.length && <p className="py-8 text-center text-sm text-slate-500">لا توجد أحداث أمان مسجلة بعد.</p>}</div></CardContent></Card></div><div className="grid gap-6 xl:grid-cols-[.9fr_1.1fr]"><Card className="border-white/8 bg-[#111823] shadow-panel"><CardContent className="p-5"><h2 className="font-bold text-white">تسجيل حدث أمان</h2><form className="mt-4 space-y-3" onSubmit={(event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const form = new FormData(event.currentTarget); onRecord({ eventType: String(form.get("eventType")), severity: String(form.get("severity")), status: String(form.get("status")), title: String(form.get("title")), details: String(form.get("details") || "") || undefined }); event.currentTarget.reset(); }}><div className="grid grid-cols-3 gap-2"><select name="eventType" className={inputClass}><option value="suspicious_login">دخول مشبوه</option><option value="backup">نسخ احتياطي</option><option value="security_change">تغيير أمان</option></select><select name="severity" className={inputClass}><option value="info">معلومة</option><option value="warning">تحذير</option><option value="critical">حرج</option></select><select name="status" className={inputClass}><option value="open">مفتوح</option><option value="resolved">معالج</option><option value="success">ناجح</option><option value="failed">فاشل</option></select></div><Input required name="title" placeholder="عنوان الحدث" className={inputClass} /><textarea name="details" placeholder="تفاصيل مختصرة" className="min-h-20 w-full rounded-xl border border-white/10 bg-white/[.025] p-3 text-sm text-white outline-none" /><Button disabled={pending} className="w-full bg-[#F5B800] text-[#0D1117] hover:bg-[#ffd23f]">تسجيل الحدث</Button></form></CardContent></Card><Card className="border-white/8 bg-[#111823] shadow-panel"><CardContent className="p-5"><h2 className="font-bold text-white">إعدادات الأمان</h2><p className="mt-1 text-sm text-slate-500">إعدادات محفوظة مركزياً، منفصلة عن أسرار المزودين الخاصة بالمستأجرين.</p><div className="mt-4 space-y-3">{settings.map((setting: any) => <label key={setting.id} className="flex items-center justify-between rounded-xl border border-white/8 bg-white/[.02] p-3 text-sm text-slate-300">{setting.settingKey}<input type="checkbox" defaultChecked={setting.isEnabled} disabled={pending} onChange={(event) => onSaveSetting({ settingKey: setting.settingKey, isEnabled: event.target.checked, value: setting.value ?? undefined })} className="accent-[#F5B800]" /></label>)}{!settings.length && <Button disabled={pending} variant="outline" onClick={() => onSaveSetting({ settingKey: "platform_audit_guard", isEnabled: true })} className="w-full border-white/10 text-white hover:bg-white/5 hover:text-white">تهيئة حراسة التدقيق</Button>}</div></CardContent></Card></div></section>; }
function SecurityCard({ title, text }: { title: string; text: string }) { return <Card className="border-white/8 bg-[#111823]"><CardContent className="p-5"><ShieldAlert className="h-5 w-5 text-[#F5B800]" /><h2 className="mt-4 font-bold text-white">{title}</h2><p className="mt-2 text-sm leading-7 text-slate-500">{text}</p></CardContent></Card>; }
function SettingsCenter({ security, pending, onSaveSetting }: any) { const settings = security?.settings ?? []; return <section className="grid gap-6 md:grid-cols-3"><SecurityCard title="الإعدادات العامة" text="اسم المنتج والهوية واللغات مُدارة من إعدادات المشروع. تُحفظ إعدادات كل مالك مولد داخل مساحته المعزولة." /><SecurityCard title="التكاملات" text="بوابات الدفع الإلكتروني وWhatsApp وSMS في حالة إعداد مؤجل. لا يوجد مزود متصل أو إرسال حي حتى طلب التفعيل الصريح." /><Card className="border-white/8 bg-[#111823]"><CardContent className="p-5"><h2 className="font-bold text-white">إعدادات الحماية</h2><p className="mt-2 text-sm leading-7 text-slate-500">مفاتيح حراسة المنصة المسجلة مركزياً.</p><div className="mt-4 space-y-3">{settings.map((setting: any) => <label className="flex items-center justify-between gap-3 rounded-xl border border-white/8 bg-white/[.02] p-3 text-sm text-slate-300" key={setting.id}>{setting.settingKey}<input type="checkbox" defaultChecked={setting.isEnabled} onChange={(event) => onSaveSetting({ settingKey: setting.settingKey, isEnabled: event.target.checked, value: setting.value ?? undefined })} disabled={pending} className="accent-[#F5B800]" /></label>)}{!settings.length && <Button disabled={pending} onClick={() => onSaveSetting({ settingKey: "platform_audit_guard", isEnabled: true })} className="w-full bg-[#F5B800] text-[#0D1117] hover:bg-[#ffd23f]">تهيئة حراسة التدقيق</Button>}</div></CardContent></Card></section>; }
